'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat64Array = require( '@stdlib/assert/is-same-float64array' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var Float64Array = require( '@stdlib/array/float64' );
var csignum = require( './../lib/assign.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof csignum, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function evaluates the signum function of a double-precision complex floating-point number', function test( t ) {
	var expected;
	var out;
	var v;

	out = new Float64Array( 2 );
	v = csignum( 3.0, -4.0, out, 1, 0 );

	expected = new Float64Array( [ 0.6, -0.8 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 4 );
	v = csignum( 3.0, -4.0, out, 2, 0 );

	expected = new Float64Array( [ 0.6, 0.0, -0.8, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 4 );
	v = csignum( 3.0, -4.0, out, 2, 1 );

	expected = new Float64Array( [ 0.0, 0.6, 0.0, -0.8 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 4 );
	v = csignum( 3.0, -4.0, out, -2, 3 );

	expected = new Float64Array( [ 0.0, -0.8, 0.0, 0.6 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function evaluates the complex signum function', function test( t ) {
	var expected;
	var out;

	out = new Float64Array( 2 );
	csignum( 0.0, 2.0, out, 1, 0 );

	expected = new Float64Array( [ 0.0, 1.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 2 );
	csignum( -5.0, 0.0, out, 1, 0 );

	expected = new Float64Array( [ -1.0, 0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 2 );
	csignum( 6.0, -8.0, out, 1, 0 );

	expected = new Float64Array( [ 0.6, -0.8 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 2 );
	csignum( 4.0, -0.0, out, 1, 0 );

	expected = new Float64Array( [ 1.0, -0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns a `NaN` if provided a `NaN`', function test( t ) {
	var out;

	out = new Float64Array( 2 );
	csignum( NaN, 3.0, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );

	out = new Float64Array( 2 );
	csignum( 5.0, NaN, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );

	out = new Float64Array( 2 );
	csignum( NaN, NaN, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `+0` if provided `+0`', function test( t ) {
	var expected;
	var out;

	out = new Float64Array( 2 );
	csignum( 0.0, 0.0, out, 1, 0 );

	expected = new Float64Array( [ 0.0, 0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', function test( t ) {
	var expected;
	var out;

	out = new Float64Array( 2 );
	csignum( -0.0, -0.0, out, 1, 0 );

	expected = new Float64Array( [ -0.0, -0.0 ] );

	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns a `NaN` if provided `infinity`', function test( t ) {
	var out;

	out = new Float64Array( 2 );
	csignum( PINF, PINF, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns a `NaN` if provided `-infinity`', function test( t ) {
	var out;

	out = new Float64Array( 2 );
	csignum( NINF, NINF, out, 1, 0 );
	t.strictEqual( isnan( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnan( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});
